CREATE TYPE "ScanType" AS ENUM ('MESSAGE', 'URL', 'SCREENSHOT', 'JOB_OFFER');
CREATE TYPE "RiskLevel" AS ENUM ('LOW', 'MEDIUM', 'HIGH');
CREATE TYPE "ScenarioStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "MembershipRole" AS ENUM ('OWNER', 'ADMIN', 'MEMBER');

ALTER TABLE "ScenarioAttempt" DROP CONSTRAINT "ScenarioAttempt_userId_fkey";
ALTER TABLE "Scenario" DROP COLUMN "category", ADD COLUMN "categoryId" TEXT NOT NULL, ADD COLUMN "content" JSONB NOT NULL, ADD COLUMN "deletedAt" TIMESTAMP(3), ADD COLUMN "status" "ScenarioStatus" NOT NULL DEFAULT 'DRAFT', ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL, DROP COLUMN "difficulty", ADD COLUMN "difficulty" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "ScenarioAttempt" ADD COLUMN "answers" JSONB, ADD COLUMN "reactionMs" INTEGER;
ALTER TABLE "User" ALTER COLUMN "safetyScore" SET DEFAULT 50;

CREATE TABLE "PushToken" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "token" TEXT NOT NULL, "platform" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PushToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationLog" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "kind" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "deliveredAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "NotificationLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Profile" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "displayName" TEXT, "avatarUrl" TEXT, "timezone" TEXT, "quietHoursStart" INTEGER, "quietHoursEnd" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Profile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "refreshTokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "deviceName" TEXT, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioCategory" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ScenarioCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LearningProgress" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "categoryId" TEXT NOT NULL, "completed" INTEGER NOT NULL DEFAULT 0, "mastery" INTEGER NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LearningProgress_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DailyChallenge" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "scenarioId" TEXT NOT NULL, "date" DATE NOT NULL, "completedAt" TIMESTAMP(3), CONSTRAINT "DailyChallenge_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiScan" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" "ScanType" NOT NULL, "risk" "RiskLevel" NOT NULL, "score" INTEGER NOT NULL, "summary" TEXT NOT NULL, "redFlags" JSONB NOT NULL, "action" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiScan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Achievement" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "icon" TEXT NOT NULL, CONSTRAINT "Achievement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserAchievement" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "achievementId" TEXT NOT NULL, "earnedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "UserAchievement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Group" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "inviteCode" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Group_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GroupMember" ("id" TEXT NOT NULL, "groupId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" "MembershipRole" NOT NULL DEFAULT 'MEMBER', CONSTRAINT "GroupMember_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationPreference" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "dailyChallenge" BOOLEAN NOT NULL DEFAULT true, "threatAlerts" BOOLEAN NOT NULL DEFAULT true, "monthlyReport" BOOLEAN NOT NULL DEFAULT true, "preferredHour" INTEGER, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "NotificationPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "actorId" TEXT, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));

